// src/stores/counter.js
import { defineStore } from 'pinia'
import { reactive } from 'vue'

// 第一个参数是唯一的 storeId
export const useStore = defineStore('counter', () => {
  // 1. State (数据)
  const Resolution = reactive({
		window:1920,
		height:1080
	})

  // // 2. Getters (计算属性)
  // const doubleCount = computed(() => count.value * 2)

  // // 3. Actions (方法)
  function setResolutionHeight(val) {
 
    Resolution.height = val
  }

  // 必须把需要暴露的变量和方法 return 出去
  return { Resolution ,setResolutionHeight}
})