import { useStore } from '@/store/index'
import { onActivated, onDeactivated, onMounted, onUnmounted, ref, watch } from 'vue'

export default function useScreenScale(defaultWidth = 1920, defaultHeight = 1080) {
  const { Resolution } = useStore()
  const scale = ref(1)

  // 1. 定义一个响应式的高度
  // 优先使用 Store 中的高度，如果没有则使用默认传参
  const currentHeight = ref(Resolution?.height || defaultHeight)
  // 宽度通常是固定的设计稿宽度，如果有动态需求也可以改成 ref
  const currentWidth = ref(defaultWidth)

  // 2. 监听 Store 的变化，实时更新 currentHeight
  watch(
    () => Resolution?.height,
    (newVal) => {
      if (newVal) {
        console.log('高度更新为:', newVal)
        currentHeight.value = newVal
        // 高度变化后，必须立即重新计算样式（特别是 margin）
        updateScale()
      }
    }
  )

  const screenStyle = ref({
    transformOrigin: 'left top',
    width: `${currentWidth.value}px`,
    // 初始化高度
    height: `${currentHeight.value}px`,
    overflow: 'hidden',
    transition: 'transform 0.3s'
  })

  // 防抖函数
  const debounce = (fn, delay) => {
    let timer = null
    return function (...args) {
      if (timer) clearTimeout(timer)
      timer = setTimeout(() => {
        fn.apply(this, args)
      }, delay)
    }
  }

  const updateScale = () => {
    const w = window.innerWidth
    
    // 获取当前最新的高度值
    const h = currentHeight.value 
    const dw = currentWidth.value

    // 3. 计算比例 (宽度铺满)
    const ratio = w / dw
    scale.value = ratio

    // 4. 重新组装样式
    screenStyle.value = {
      ...screenStyle.value,
      // 关键：确保 CSS height 也是最新的
      height: `${h}px`,
      width: `${dw}px`, // 确保宽度也在
      transform: `scale(${scale.value})`,

      // 5. 动态修正占位高度
      // 公式：(实际高度 * 缩放比例) - 实际高度
      // 如果 scale < 1，marginBottom 为负数，把下方的空白吸上来
      // marginBottom: `${(h * scale.value) - h}px`,

      // 动态修正右侧空白
      // marginRight: `${(dw * scale.value) - dw}px`
    }
  }

  const onResize = debounce(updateScale, 200)

  onMounted(() => {
    updateScale()
    window.addEventListener('resize', onResize)
  })

  onUnmounted(() => {
    window.removeEventListener('resize', onResize)
  })

  onActivated(() => {
    updateScale()
    window.addEventListener('resize', onResize)
  })

  onDeactivated(() => {
    window.removeEventListener('resize', onResize)
  })

  return {
    scale,
    screenStyle
  }
}