import { isLoggedIn } from '@/utils/auth'
import { createRouter, createWebHashHistory } from 'vue-router'

const router = createRouter({
	history: createWebHashHistory(process.env.BASE_URL),
	routes: [
		{
			path: '/',
			redirect: "/login",
		},
		{
			path: '/login',
			name: 'login',
			component: () => import("../views/LoginPage.vue"),
			meta: {
				public: true
			}
		},
		{
			path: '/welcome',
			name: 'welcome',
			component: () => import("../views/WelcomePage.vue"),
			meta: {
				requiresAuth: true
			}
		},
		{
			path: '/config',
			name: 'config',
			component: () => import("../views/ConfigPage.vue")
		},
		{
			path: '/xieyi',
			name: 'xieyi',
			component: () => import("../views/XieyiPage.vue")
		},
		{
			path:'/page/',
			name:"page",
			redirect:"/page/xtkz",
			component:()=>import('../components/layout/LayoutComponent.vue'),
			meta: {
				requiresAuth: true
			},
			children:[

				{
					path: '/page/xmzl',
					name: 'pageXmzl',
					component: () => import("../views/XmzlPage.vue"),
					meta: {
						title: '项目总览'
					}
				},
				{
					path: '/page/zlzh',
					name: 'pageZlzh',
					component: () => import("../views/ZlzhPage.vue"),
					meta: {
						title: '多圆组合管幕'
					}
				},
				{
					path: '/page/zhzh',
					name: 'pageZhzh',
					component: () => import("../views/ZhzhPage.vue"),
					meta: {
						title: '支护结构一体化施工'
					}
				},
				{
					path: '/page/sxtjkw',
					name: 'pageSxtjkw',
					component: () => import("../views/SxtjkwPage.vue"),
					meta: {
						title: '上下层开挖'
					}
				},
				{
					path: '/page/dyzhgm',
					name: 'pageDyzhgm',
					component: () => import("../views/DyzhgmPage.vue"),
					meta: {
						title: '顶进组合管幕'
					}
				},
				{
					path: '/page/bxjztc',
					name: 'pageBxjztc',
					component: () => import("../views/BxjztcPage.vue"),
					meta: {
						title: '并行建造台车'
					}
				},
				{
					path: '/page/sfjstc',
					name: 'pageSfjstc',
					component: () => import("../views/SfjstcPage.vue"),
					meta: {
						title: '始发接收台车'
					}
				},
				{
					path: '/page/zzj',
					name: 'pageZzj',
					component: () => import("../views/ZzjPage.vue"),
					meta: {
						title: '装载机'
					}
				},

			]
		},


	],
})

router.beforeEach((to) => {
	if (to.path === '/login' && isLoggedIn()) {
		return '/welcome'
	}

	if (!to.meta.public && !isLoggedIn()) {
		return {
			path: '/login',
			query: {
				redirect: to.fullPath
			}
		}
	}
})

export default router
