const AUTH_STORAGE_KEY = 'sdu_web_auth_token'
const USERNAME = 'admin'
const PASSWORD = '123456'
const AUTH_TOKEN = 'sdu-web-front-login'

function getStorage() {
  if (typeof localStorage === 'undefined') {
    return null
  }

  return localStorage
}

function login(username, password) {
  const storage = getStorage()
  const passed = username === USERNAME && password === PASSWORD

  if (passed && storage) {
    storage.setItem(AUTH_STORAGE_KEY, AUTH_TOKEN)
  }

  return passed
}

function logout() {
  const storage = getStorage()

  if (storage) {
    storage.removeItem(AUTH_STORAGE_KEY)
  }
}

function isLoggedIn() {
  const storage = getStorage()

  return storage ? storage.getItem(AUTH_STORAGE_KEY) === AUTH_TOKEN : false
}

module.exports = {
  AUTH_STORAGE_KEY,
  login,
  logout,
  isLoggedIn
}
