<template>
  <div class="screen-container">
    <div class="screen-content" :style="screenStyle">
      <router-view></router-view>
    </div>
  </div>
</template>

<script setup>
import useScreenScale from '@/hooks/useScreenScale'
import { useStore } from '@/store/index'
import { onMounted, onUnmounted } from 'vue'

const { Resolution, setResolutionHeight } = useStore()
// 1. 定义设计稿宽度 (必须和你 hooks 里的 defaultWidth 保持一致)
const designWidth = 1920

const { screenStyle } = useScreenScale(Resolution.window, Resolution.height)

// 核心计算函数
const handleResize = () => {
  const w = window.innerWidth
  const h = window.innerHeight

  // 2. 实时计算当前的缩放比例
  // 注意：这里不要用 hooks 返回的 scale，因为可能会有更新延迟，直接算最稳
  const currentRatio = w / designWidth

  // 3. 使用你的公式：高度 / scale
  let calculatedHeight = h / currentRatio

  // 4. (可选) 最小高度兜底
  // 如果算出来的高度小于 900（设计稿的最小高度），强制设为 900，防止内容重叠
  // 但通常全屏页面不需要这个，除非你确实有内容溢出的风险
  if (calculatedHeight < 900) {
    calculatedHeight = 900
  }

  // 5. 更新 Store
  setResolutionHeight(calculatedHeight)
}

onMounted(() => {
  handleResize() // 初始化执行一次
  window.addEventListener('resize', handleResize)
})

onUnmounted(() => {
  window.removeEventListener('resize', handleResize)
})

</script>

<style scoped>
/* 1. 外层容器：定基调 */
.screen-container {
  z-index: 2;
  position: relative;
  /* 必须是 relative/absolute/fixed 之一，为子元素定位做准备 */
  overflow: hidden;
  background-color: #0f1225;
  height: 100vh;
  /* 兜底的深色背景，防止图片加载失败显示白底 */
  /* 注意：不要直接在这里加 filter: blur()，否则里面的内容也会糊掉 */
}
</style>